------------ import ------------
local kCookie =  CS.Engine.Lib.KCookie
local questComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
local cs_coroutine = require 'XLua.cs_coroutine'
local animationName = "CommonMainlineTaskTipsNodeGo"
local KTool = CS.Engine.Lib.KTool
local FishingUtils = import('Game.UI.Fishing.FishingUtils')
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
------------ import ------------

--Game.UI.FightReady.UIMainChapter.UICommonMainlineTaskTipsNode
---@class UICommonMainlineTaskTipsNode
---@field Env                           	UICommonMainlineTaskTipsNode
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field PromptUpItem                  	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
---@field MaskState                     	UnityEngine.RectTransform               
---@field TxtState                      	UnityEngine.RectTransform                                       
local UICommonMainlineTaskTipsNode = Class("UICommonMainlineTaskTipsNode")
function UICommonMainlineTaskTipsNode:__init()
    self._data = nil
    self._taskVo = nil
end

function UICommonMainlineTaskTipsNode:__delete()
    self._data = nil
    self._taskVo = nil
end

function UICommonMainlineTaskTipsNode:Awake()
    self.Slider = KTool.GetComponent(self.Slider.gameObject, typeof(CS.UnityEngine.UI.Slider))
end

function UICommonMainlineTaskTipsNode:Start()
    SetButtonAction(self.BtnNode, Bind(self, self.OnShowInfo))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnGo))
end

function UICommonMainlineTaskTipsNode:Refresh(data)
    if not data then
        return 
    end
    self._data = data

    if checkNumber(self._data.type) == Constants.TaskType.RegionTask then 
        self:FillRegionInfo()
    else
        self:FillSelf()
    end
end

function UICommonMainlineTaskTipsNode:OnShowInfo()
    if FishingUtils.IsAutoing() then
        return
    end

    ---@type UnityEngine.Animation
    local animation = KTool.GetComponent(self.Root.gameObject, typeof(CS.UnityEngine.Animation))
    animation:Play(animationName)

    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self._co = cs_coroutine.start(function()
        local time = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 24).num)
        coroutine.yield(CS.UnityEngine.WaitForSeconds(time))
        local animation = KTool.GetComponent(self.Root.gameObject, typeof(CS.UnityEngine.Animation))
        animation:Play("CommonMainlineTaskTipsNodeBack")
    end)
end

function UICommonMainlineTaskTipsNode:OnBtnGo()
    if FishingUtils.IsAutoing() then
        return
    end

    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    --blocker:AddCondition("__ExecuteJump")
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    xTry(function()
        cs_coroutine.start(function()
            local row
            if checkNumber(self._data.type) == Constants.TaskType.RegionTask then 
                row = goodsConfMgr:GetJumpModuleRow(290 + checkNumber(self._taskVo.regionBelong))
            else
                row = goodsConfMgr:GetJumpModuleRow(100)
            end

            if row then
                cs_coroutine.yield_return(goodsConfMgr:ExecuteJump(row, {}, 0, true))
                kCookie.Set("UICommonMainlineTaskTipsNode", 0)
                KTool.SafeDelete(self.controller.gameObject)
            end
            --blocker:RemoveCondition("__ExecuteJump")
        end)
    end, function()
        print_to_file(debug.traceback())
        --blocker:RemoveCondition("__ExecuteJump")
        KTool.SafeDelete(self.controller.gameObject)
    end)
end

function UICommonMainlineTaskTipsNode:FillRegionInfo()
    self._co = cs_coroutine.start(function()
        local time = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 24).num)
        coroutine.yield(CS.UnityEngine.WaitForSeconds(time))
        local animation = KTool.GetComponent(self.Root.gameObject, typeof(CS.UnityEngine.Animation))
        animation:Play("CommonMainlineTaskTipsNodeBack")
    end)

    self._taskVo = ActionUtils.GetRegionTaskVo(self._data.taskId)
    CfUtils.SetActive(self.TextChapter, false)
    if not self._taskVo then return end

    local vo = ActionUtils.GetRegionPrimaryMapVo(self._taskVo.regionBelong)
    if vo then
        CfUtils.FillText(self.TextName, localize("_name_调查任务", {_name_ = tostring(vo.name)}))
    end
    CfUtils.FillText(self.TextDesc, tostring(self._taskVo.name))

    CfUtils.FillText(self.TitleText, localize("_num1_/_num2_", {_num1_ = checkNumber(self._data.progress), _num2_ = checkNumber(self._taskVo.taskContenNum)}))
    self.Slider.value = checkNumber(self._data.progress) / checkNumber(self._taskVo.taskContenNum)
end

function UICommonMainlineTaskTipsNode:FillSelf()
    self._co = cs_coroutine.start(function()
        local time = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 24).num)
        coroutine.yield(CS.UnityEngine.WaitForSeconds(time))
        local animation = KTool.GetComponent(self.Root.gameObject, typeof(CS.UnityEngine.Animation))
        animation:Play("CommonMainlineTaskTipsNodeBack")
    end)

    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self._data.questId)
    if questVo then
        self._taskVo = QuestConfMgr:GetInstance():GetMainTaskQuestVo(questVo.task)
        CfUtils.FillText(self.TextChapter, questVo.label)
        CfUtils.FillText(self.TextName, questVo.name)
    end
    if not self._taskVo then return end

    CfUtils.FillText(self.TextDesc, tostring(self._taskVo.taskTitle))

    local taskData = questComponent:GetCurTaskInfo()
    CfUtils.FillText(self.TitleText, localize("_num1_/_num2_", {_num1_ = checkNumber(taskData.progress), _num2_ = checkNumber(self._taskVo.taskContenNum)}))
    self.Slider.value = checkNumber(taskData.progress) / checkNumber(self._taskVo.taskContenNum)
end

function UICommonMainlineTaskTipsNode:OnDestroy()
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    kCookie.Set("UICommonMainlineTaskTipsNode", 0)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UICommonMainlineTaskTipsNode